'use client';
import Link from 'next/link';import Image from 'next/image';import {Menu,X} from 'lucide-react';import {useState} from 'react';import {nav,t} from '@/lib/content';import {useLanguage} from './LanguageProvider';
export function Header(){const{lang,setLang}=useLanguage(),[open,setOpen]=useState(false);return <header className="sticky top-0 z-50 border-b border-white/10 bg-[#0a241df5] text-white backdrop-blur"><div className="container flex h-20 items-center justify-between gap-5"><Link href="/" className="flex items-center gap-3" aria-label="Orienteering Georgia home"><Image src="/images/geof-logo.jpg" alt="" width={160} height={48} className="h-12 w-auto max-w-[9rem] rounded-md bg-white object-contain px-2 py-1" priority/><span className="leading-tight"><b>ორიენტირება</b><small className="block text-[10px] tracking-[.18em] text-white/60">GEORGIA</small></span></Link><nav className="desktop flex items-center gap-5 text-[13px] font-semibold">{nav.map(n=><Link key={n[0]} className="hover:text-orange-400" href={n[0]}>{t(lang,n[1],n[2])}</Link>)}</nav><div className="flex items-center gap-3"><button className="text-xs font-bold" onClick={()=>setLang(lang==='ka'?'en':'ka')} aria-label="Switch language">{lang==='ka'?'ქართული | ENG':'KA | English'}</button><button className="mobile" onClick={()=>setOpen(!open)} aria-label="Menu">{open?<X/>:<Menu/>}</button></div></div>{open&&<nav className="mobile container grid gap-1 pb-5">{nav.map(n=><Link onClick={()=>setOpen(false)} className="rounded-lg px-3 py-2 hover:bg-white/10" key={n[0]} href={n[0]}>{t(lang,n[1],n[2])}</Link>)}</nav>}</header>}
